<h2>Keuangan daerah</h2><p class="muted">Anggaran, rincian APBD, target, LRA, mandatory, transfer, dan kawasan. LRA diisi sebagai nilai kumulatif sampai bulan laporan; jangan menjumlahkan antarbulan.</p><form method="get" class="panel filters"><label>Tahun<input name="tahun" type="number" min="2000" max="2100" value="<?= $year ?>"></label><button>Tampilkan</button></form>
<div class="panel table-wrap"><table><thead><tr><th>Kategori / kode</th><th>Nama</th><th>APBD</th><th>Bulan</th><th>Nilai</th><th>Aksi</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= $esc($r['jenis']) ?><br><small><?= $esc($r['kode']) ?></small></td><td><?= $esc($r['nama']) ?></td><td><?= $esc($r['status_apbd']) ?></td><td><?= $r['bulan']?:'Tahunan' ?></td><td class="num"><?= $rupiah($r['nilai']) ?></td><td><?php if($actor['role']==='admin'): ?><details><summary>Ubah</summary><form method="post" action="<?= $url('save/finance') ?>"><?= $token ?><?php foreach(['id','jenis','tahun','bulan','status_apbd','kode','nama'] as $f): ?><input type="hidden" name="<?= $f ?>" value="<?= $esc($r[$f]) ?>"><?php endforeach; ?><label>Nilai<input type="number" required min="0" step="0.01" name="nilai" value="<?= $esc($r['nilai']) ?>"></label><button>Simpan</button></form></details><form method="post" action="<?= $url('remove/finance/'.$r['id']) ?>" data-confirm="Hapus data keuangan ini?"><?= $token ?><button class="danger">Hapus</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if($actor['role']==='admin'): ?><form method="post" class="panel grid" action="<?= $url('save/finance') ?>"><?= $token ?><label>Kategori<select name="jenis"><?php foreach(['anggaran'=>'Anggaran ringkas','apbd'=>'Rincian APBD','target'=>'Target APBD (kumulatif Rp)','lra'=>'LRA (kumulatif Rp)','mandatory'=>'Mandatory','tkdd'=>'Dana TKDD','kawasan'=>'Kawasan strategis (anggaran Rp)'] as $v=>$n): ?><option value="<?= $v ?>"><?= $n ?></option><?php endforeach; ?></select></label><label>Tahun<input required type="number" name="tahun" min="2000" max="2100" value="<?= $year ?>"></label><label>Bulan (0 = tahunan)<input required type="number" name="bulan" min="0" max="12" value="0"></label><label>Status APBD<select name="status_apbd"><option value="murni">Murni</option><option value="perubahan">Perubahan</option></select></label><label>Kode kategori/rekening<input required name="kode" maxlength="50"></label><label>Nama kategori/rekening<input required name="nama" maxlength="180"></label><label>Nilai (Rp, tanpa titik ribuan)<input required name="nilai" type="number" min="0" step="0.01"></label><button>Simpan</button></form><?php endif; ?>
